 count=r['metrics']['targets/sunday_main/F3_role_pbp_tree']['position'][pos]['n'];vals=[r['metrics'][t+'/sunday_main/F3_role_pbp_'+kind]['position'][pos]['mae'] for t in ['targets','carries','fantasy_points_ppr'] for kind in ['tree','neural']]
 lines.append('| '+pos+f' | {count} | '+' | '.join(f'{v:.3f}' for v in vals)+' |')
